#include <vector>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int maxNonOverlapping(vector<int>& nums, int target) {
        unordered_set<int> seen = {0};
        int sum = 0, count = 0;

        for (int n : nums) {
            sum += n;
            if (seen.count(sum - target)) {
                count++;
                seen = {0};
                sum = 0;
            } else {
                seen.insert(sum);
            }
        }

        return count;
    }
};
